def transform(grid):
    g=[row[:] for row in grid]
    R=len(g);C=len(g[0])
    centers=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if g[r][c]==6 and g[r-1][c]==6 and g[r+1][c]==6 and g[r][c-1]==6 and g[r][c+1]==6:
                centers.append((r,c))
    template=None
    for ctr in centers:
        r,c=ctr
        has3=any(g[rr][cc]==3 for rr in range(max(0,r-5),min(R,r+6)) for cc in range(max(0,c-5),min(C,c+6)))
        if has3:
            template=ctr;break
    if template is None: return g
    r0,c0=template
    cells=[(rr-r0,cc-c0,g[rr][cc]) for rr in range(R) for cc in range(C) if g[rr][cc]!=0]
    for ctr in centers:
        if ctr==template: continue
        r,c=ctr
        for dr,dc,v in cells:
            rr,cc=r+dr,c+dc
            if 0<=rr<R and 0<=cc<C:
                g[rr][cc]=v
